parameters.jsCode:
const items = $input.all();
const updatedItems = items.map((item) => {
  const base64Url = item?.json?.data;
  const url = `data:image/png;base64,${base64Url}`;
  return { url };
});
return updatedItems;

parameters.jsonBody:
={
  "model": "kling-2.6/image-to-video",
  "callBackUrl": "https://your-domain.com/api/callback",
  "input": {
    "prompt": "Professional fashion product video of elegant Indian female model showcasing a traditional saree in a clean studio setup. VIDEO SEQUENCE: Model begins standing center-frame in full-length front view, takes 2-3 graceful steps forward toward camera showing saree fall and pleats movement. She pauses with a confident smile, then smoothly rotates 180 degrees showing side profile drape and hip fit, continuing the turn to reveal back view with blouse design and pallu fall. Model then turns back to front, gracefully lifts and spreads the pallu with her hand showcasing border work, embroidery and design details. She performs an elegant slow twirl showing 360-degree view as the fabric flows beautifully. Camera captures natural fabric movement, weight and flow throughout. Professional three-point studio lighting highlights intricate patterns, zari work, sequins and border details. Multiple focal depths - starting wide full-length, moving to mid-shots, with moments of close-up focus on fabric texture, embroidery craftsmanship and border scallops. Clean complementary background (warm beige for light sarees, soft white for dark sarees). Cinematic smooth transitions between movements. Natural, sophisticated presentation showcasing the complete saree from every important angle - front pleats, side drape, back design, pallu work, and overall elegance. The video should feel like a premium e-commerce product showcase with fluid motion and professional fashion videography style.",
    "image_urls": [
      "{{ $json['FRONT Image URL'] }}"
    ],
    "sound": false,
    "duration": "10"
  }
}

